function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const O = '#0d0a08', R = '#d43030', RL = '#f05050', RD = '#8b1a1a';
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };
  const heartAt = (x, y) => {
    const lobe = (cx, cy) => (x - cx) * (x - cx) + (y - cy) * (y - cy) <= 49;
    if ((lobe(24, 23) || lobe(40, 23)) && y >= 16 && y <= 36) return true;
    if (y < 28 || y > 50) return false;
    const t = (y - 28) / 22;
    const hw = Math.floor(16 * (1 - t) + 1);
    return Math.abs(x - 32) <= hw;
  };
  for (let y = 14; y < 52; y++) for (let x = 14; x < 50; x++) {
    if (!heartAt(x, y)) continue;
    let c = R;
    if (x <= 27 && y <= 26) c = RL;
    if (x >= 36 && y >= 38) c = RD;
    px(x, y, 1, 1, c);
  }
  for (let y = 14; y < 52; y++) for (let x = 14; x < 50; x++) {
    if (!heartAt(x, y)) continue;
    const edge = !heartAt(x - 1, y) || !heartAt(x + 1, y) || !heartAt(x, y - 1) || !heartAt(x, y + 1);
    if (edge) px(x, y, 1, 1, O);
  }
  px(22, 20, 3, 2, RL);
}
